-- Step 1: Clear dependent data (safe for dev/demo)
TRUNCATE booking_tickets, bookings, time_slots RESTART IDENTITY CASCADE;

-- Step 2: Add location_id to time_slots
ALTER TABLE time_slots
  ADD COLUMN IF NOT EXISTS location_id UUID REFERENCES locations(id) ON DELETE CASCADE;

CREATE INDEX IF NOT EXISTS idx_time_slots_location_id ON time_slots(location_id);

-- Step 3: Re-seed 125 slots (5 locations × 5 dates × 5 times)
-- UUID pattern: 44{loc2}{date2}{slot2}-0000-0000-0000-000000000001
-- Locations: 01=Chennai 02=Bangalore 03=Hyderabad 04=Mumbai 05=Delhi
-- Dates:     01=Jun15   02=Jun16    03=Jun17      04=Jun18  05=Jun19
-- Slots:     01=9AM     02=11AM     03=1PM        04=3PM    05=5PM

